import '../l10n/hauptstaedte_en.dart';
import '../l10n/laendernamen_en.dart';
import '../services/locale_service.dart';

class Country {
  final String iso2;
  final String nameDe;
  final String capitalDe;
  final String flagEmoji;
  final double latitude;
  final double longitude;
  final String region;
  final int gdp;
  final int population;

  const Country({
    required this.iso2,
    required this.nameDe,
    required this.capitalDe,
    required this.flagEmoji,
    required this.latitude,
    required this.longitude,
    required this.region,
    required this.gdp,
    required this.population,
  });

  // Computed statt gespeichertes Feld: jede bestehende Verwendungsstelle
  // (`country.name` — sehr viele Stellen im gesamten Code) bleibt unverändert
  // funktionsfähig UND wird automatisch lokalisiert, ohne dass jede einzelne
  // Stelle angefasst werden müsste (gleiches Muster wie CountryRanking.name
  // in country_rankings.dart).
  String get name =>
      LocaleService.istEnglisch ? (laendernamenEn[iso2] ?? nameDe) : nameDe;

  // Nur ~44 der 197 Hauptstädte unterscheiden sich zwischen Deutsch und
  // Englisch (z.B. Rom/Rome, Wien/Vienna) — hauptstaedteEn deckt nur diese
  // ab, der Rest fällt auf capitalDe zurück (identisch in beiden Sprachen).
  String get capital =>
      LocaleService.istEnglisch ? (hauptstaedteEn[iso2] ?? capitalDe) : capitalDe;
}

